<?php
declare(strict_types=1);define('_GNUBOARD_',true);require_once __DIR__.'/../../bridge/package-migration.php';
$dsn=getenv('NOA_MYSQL_DSN');if(!str_contains((string)$dsn,'dbname=noa_inline_edit_test;'))throw new RuntimeException('isolated_database_required');$db=new PDO($dsn,'root','noa-test-only',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
function ok(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);}
$root=sys_get_temp_dir().'/noa-package-native-'.bin2hex(random_bytes(6));mkdir($root,0700);$order=$root.'/category-order.json';file_put_contents($order,json_encode(['playlists'=>[['id'=>str_repeat('e',24),'title'=>'사연 목록','group'=>'story','keys'=>['single:story:one'],'requestId'=>'fixture-only-request']]]));
$db->prepare('INSERT INTO noa_documents(doc_key,kind,payload,revision,updated_by) VALUES(?,?,?,?,?)')->execute(['single:story:one','story',json_encode(['genreId'=>'your-story','title'=>'사연곡','body'=>['lyricsBlock'=>'가사','other'=>['preserve'=>true]]]),1,'fixture']);
$old=$db->query('SELECT COUNT(*) FROM noa_document_history')->fetchColumn();ok(nup_register_catalog($db,str_repeat('b',64))===0,'uninstalled legacy catalog stays read-only');$before=nup_inventory($db,$order);$plan=nup_plan($before);ok(count($plan['changes'])>0,'initial migration changes');$result=nup_apply($db,$plan,$order,$root.'/packages');ok($result['oldMediaAndSourceArchivesPreserved'],'media preserved');ok(hash('sha256',file_get_contents($order))===$before['orderSha256'],'legacy order file untouched');
$again=nup_plan(nup_inventory($db,$order));ok(count($again['changes'])===0,'migration idempotent');ok((int)$db->query('SELECT COUNT(*) FROM noa_document_history')->fetchColumn()>(int)$old,'history appended');
$r=$db->query("SELECT payload FROM noa_documents WHERE doc_key='playlist:custom:".str_repeat('e',24)."'")->fetchColumn();$p=json_decode($r,true);ok($p['packageType']==='playlist'&&count($p['body']['members'])===1,'ordinary playlist one complete record, no ten-song rule');
$export=glob($root.'/packages/records/*.json');ok(count($export)===$result['files'],'one export per record');foreach($export as $path){$s=json_decode(file_get_contents($path),true,512,JSON_THROW_ON_ERROR);ok(!empty($s['record']['packageSchema'])&&is_int($s['revision']),'full JSON readback');ok((fileperms($path)&0777)===0600,'private export mode');}
try{nup_apply($db,$plan,$order,$root.'/packages');throw new RuntimeException('stale plan accepted');}catch(DomainException $e){ok($e->getMessage()==='source_changed_replan_required','stale plan denied');}
$sourceKey='single:story:one';$revision=(int)$db->query("SELECT revision FROM noa_documents WHERE doc_key='single:story:one'")->fetchColumn();$db->beginTransaction();nup_attach_asset($db,$sourceKey,['audio_path'=>'new/audio.mp3','cover_path'=>'new/card.webp']);$db->commit();$p=json_decode($db->query("SELECT payload FROM noa_documents WHERE doc_key='single:story:one'")->fetchColumn(),true);ok($p['body']['audioFileLocation']==='new/audio.mp3'&&$p['body']['other']['preserve']===true,'verified-media manifest shares record without loss');ok((int)$db->query("SELECT revision FROM noa_documents WHERE doc_key='single:story:one'")->fetchColumn()===$revision+1,'media manifest audited');
$db->beginTransaction();ok(nup_register_catalog($db,str_repeat('b',64))===0,'existing aliases are not duplicated');$db->commit();$id=str_repeat('f',64);$batch=str_repeat('b',64);$db->prepare('INSERT INTO noa_catalog_songs VALUES(?,?,?,?,?,?)')->execute([$id,'[]','cover-reborn','ko','cover','']);$db->prepare('INSERT INTO noa_catalog_versions VALUES(?,?,?,?,?,?,?)')->execute([$batch,$id,'song',json_encode(['title'=>'새 연동 곡','youtubeUrl'=>'https://youtu.be/newvideo123','lyricsBlock'=>'새 가사']),str_repeat('1',64),'[]',1]);$db->beginTransaction();ok(nup_register_catalog($db,$batch)===1,'installed catalog registers a complete shared song');$db->commit();ok(nup_register_catalog($db,$batch)===0,'registration replay does not duplicate');$record=json_decode($db->query("SELECT payload FROM noa_documents WHERE doc_key='catalog:".$id."'")->fetchColumn(),true);ok($record['packageType']==='cover'&&$record['body']['lyricsBlock']==='새 가사','shared song preserves incoming media identity and fields');echo "UNIFIED_NATIVE_MIGRATION_BACKUP_CAS_HISTORY_PRIVATE_FILES_IDEMPOTENCY_MEDIA_OK\n";
